#include <cstddef>
#include <cstdint>
extern "C" std::int64_t job_sequencing_with_deadline(const std::int64_t*v,std::size_t n){if(!v||n<1||n>65)return -1;auto count=v[0];if(count<1||count>32||n!=1+2*static_cast<std::size_t>(count))return -1;std::int64_t d[32],p[32];std::size_t order[32];for(std::size_t i=0;i<static_cast<std::size_t>(count);i++){d[i]=v[1+2*i];p[i]=v[2+2*i];if(d[i]<0||d[i]>32||p[i]<0||p[i]>1000000)return -1;order[i]=i;}for(std::size_t i=1;i<static_cast<std::size_t>(count);i++){auto key=order[i];auto j=i;while(j>0&&p[order[j-1]]<p[key]){order[j]=order[j-1];--j;}order[j]=key;}bool slots[33]={};std::int64_t chosen=0,profit=0;for(std::size_t k=0;k<static_cast<std::size_t>(count);k++)for(int s=static_cast<int>(d[order[k]]);s>0;--s)if(!slots[s]){slots[s]=true;++chosen;profit+=p[order[k]];break;}return chosen*32000001LL+profit;}
